#!/usr/bin/env node
// Usage: node probe.mjs '<markdown source>'      -> prints exact ground-truth output with visible markers
//        node probe.mjs -f cases.json            -> JSON array of strings, prints each result
import { py } from './py.mjs';
import { readFileSync } from 'node:fs';

function show(s) {
  // Make trailing whitespace / newlines visible without altering the real bytes shown above.
  return JSON.stringify(s);
}

const argv = process.argv.slice(2);
let cases = [];
if (argv[0] === '-f') cases = JSON.parse(readFileSync(argv[1], 'utf8'));
else cases = [argv[0] ?? ''];

for (const c of cases) {
  const src = typeof c === 'string' ? c : c.a;
  const r = py(src);
  console.log('==== INPUT  ' + show(src));
  console.log('---- OUTPUT ' + show(r.stdout));
  console.log('---- RAW');
  process.stdout.write(r.stdout);
  console.log('---- rc=' + r.code + (r.stderr ? ' stderr=' + show(r.stderr) : ''));
  console.log('');
}
