import { writeFileSync } from 'node:fs';
const BS = String.fromCharCode(92);
// every printable ASCII char, plus space, tab, newline, and end-of-string
const chars = [];
for (let c = 33; c <= 126; c++) chars.push(String.fromCharCode(c));
chars.push(' ', '\t', '\n');
const cases = [];
// bare: "x\Cy"
for (const ch of chars) cases.push('x' + BS + ch + 'y');
// lone at end of string
cases.push('x' + BS);
cases.push(BS);
cases.push(BS + BS);
cases.push('x' + BS + BS + 'y');
cases.push('x' + BS + BS + BS + 'y');
cases.push('x' + BS + BS + BS + BS + 'y');
writeFileSync('/tmp/ice-b2.json', JSON.stringify(cases, null, 0));
console.log(cases.length);

